import unittest

from calc import ist_schaltjahr, mittelwert


class Tests(unittest.TestCase):
    def test_mittelwert(self):
        self.assertEqual(mittelwert([2, 4, 6]), 4)

    def test_schaltjahr(self):
        self.assertTrue(ist_schaltjahr(2024))
        self.assertTrue(ist_schaltjahr(2000))
        self.assertFalse(ist_schaltjahr(1900))
        self.assertFalse(ist_schaltjahr(2023))


if __name__ == "__main__":
    unittest.main()
